class EngineResult{EngineResult({required this.originalSize,required this.outputSize,required this.mode,this.sha256});final int originalSize,outputSize;final String mode;final String? sha256;double get saving=>originalSize==0?0:100*(1-outputSize/originalSize);double get ratio=>outputSize==0?0:originalSize/outputSize;double get bitsPerByte=>originalSize==0?0:8*outputSize/originalSize;factory EngineResult.fromJson(Map<String,dynamic>j)=>EngineResult(originalSize:(j['original_size']??j['originalSize']??j['restored_size']??0)as int,outputSize:(j['artifact_size']??j['outputSize']??j['restored_size']??0)as int,mode:(j['mode']??'decompress')as String,sha256:j['sha256']as String?);Map<String,dynamic>toJson()=>{'originalSize':originalSize,'outputSize':outputSize,'mode':mode,'sha256':sha256,'saving':saving};}
class HistoryItem{HistoryItem({required this.id,required this.action,required this.inputPath,required this.outputPath,required this.mode,required this.createdAt,required this.success,this.result,this.error});final String id,action,inputPath,outputPath,mode;final DateTime createdAt;final bool success;final EngineResult? result;final String? error;Map<String,dynamic>toJson()=>{'id':id,'action':action,'inputPath':inputPath,'outputPath':outputPath,'mode':mode,'createdAt':createdAt.toIso8601String(),'success':success,'result':result?.toJson(),'error':error};factory HistoryItem.fromJson(Map<String,dynamic>j)=>HistoryItem(id:j['id'],action:j['action'],inputPath:j['inputPath'],outputPath:j['outputPath'],mode:j['mode'],createdAt:DateTime.parse(j['createdAt']),success:j['success'],result:j['result']==null?null:EngineResult.fromJson(Map<String,dynamic>.from(j['result'])),error:j['error']);}
